(()=>{const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function update(){try{const response=await fetch('/api/runtime/verification');if(!response.ok)throw Error('Open this page through the private local runtime.');const data=await response.json();document.querySelector('#verification-status').textContent=`${data.passed} of ${data.total} capability paths verified`;document.querySelector('#verification-scope').textContent=data.fixture_scope;document.querySelector('#verification-cases').innerHTML=[...data.cases].sort((a,b)=>a.id.localeCompare(b.id)).map(c=>`<div class="file-card"><strong>${escape(c.name)}</strong><span>${c.passed?'✓ Passed':'Needs attention'}</span>${c.error?`<p class="error">${escape(c.error)}</p>`:''}${c.run_id?`<a href="workspace.html?run=${c.run_id}&capability=${c.id}">Inspect actual result ↗</a>`:''}<small>${c.output_files?.length||0} generated files · ${c.model_steps||0} Codex steps · ${c.native_steps||0} processing steps</small></div>`).join('');if(data.passed<data.total)setTimeout(update,5000);}catch(error){document.querySelector('#verification-status').textContent=error.message;}}update();})();
